 const [session,setSession]=useState(null),[profile,setProfile]=useState(null),[tab,setTab]=useState("home"),[posts,setPosts]=useState([]),[likes,setLikes]=useState(new Set()),[board,setBoard]=useState([]),[globalRank,setGlobalRank]=useState(-1),[boardMode,setBoardMode]=useState("level"),[authMode,setAuthMode]=useState("login"),[authBusy,setAuthBusy]=useState(false),[confirmationSent,setConfirmationSent]=useState(false),[verificationCode,setVerificationCode]=useState(""),[email,setEmail]=useState(""),[password,setPassword]=useState(""),[name,setName]=useState(""),[error,setError]=useState(""),[loading,setLoading]=useState(true),[postText,setPostText]=useState(""), [editingPost,setEditingPost]=useState(null),[editPostText,setEditPostText]=useState(""),[commentsOpen,setCommentsOpen]=useState(new Set()),[commentsByPost,setCommentsByPost]=useState({}),[commentText,setCommentText]=useState(""),[postImage,setPostImage]=useState(null),[chatId,setChatId]=useState(null),[messages,setMessages]=useState([]),[messageText,setMessageText]=useState(""),[conversations,setConversations]=useState([]),[difficulty,setDifficulty]=useState("beginner"),[missions,setMissions]=useState({}),[activity,setActivity]=useState({date:today(),areas:[],posts:0,likes:0,messages:0,profileChanges:0,photo:false}),[missionNotice,setMissionNotice]=useState(""),[profileView,setProfileView]=useState(null),[settingsOpen,setSettingsOpen]=useState(false),[saving,setSaving]=useState(false),[usage,setUsage]=useState(0),[liveTick,setLiveTick]=useState(0),[deleteBusy,setDeleteBusy]=useState(false),[deleteConfirm,setDeleteConfirm]=useState(false),[goals,setGoals]=useState([]),[goalTitle,setGoalTitle]=useState(""),[goalDescription,setGoalDescription]=useState(""),[goalDeadline,setGoalDeadline]=useState(""),[goalDifficulty,setGoalDifficulty]=useState("medium"),[objectiveDraft,setObjectiveDraft]=useState(""),[objectiveDate,setObjectiveDate]=useState(""),[goalBusy,setGoalBusy]=useState(false);
