const persistProfile=async patch=>{if(!session?.user?.id)throw new Error("Sessão expirada. Entre novamente.");const clean={...patch};if(Object.prototype.hasOwnProperty.call(clean,"name")){clean.name=String(clean.name||"").trim();if(clean.name.length<2)throw new Error("O nome precisa ter pelo menos 2 caracteres.");if(clean.name.length>24)throw new Error("O nome pode ter no máximo 24 caracteres.")}setSaving(true);setError("");try{const updated=await updateProgress(session.user.id,clean);setProfile(updated);if(Object.prototype.hasOwnProperty.call(clean,"name"))setName(updated.name||clean.name);return updated}catch(err){setError(err?.message||"Não foi possível salvar as alterações.");throw err}finally{setSaving(false)}};
