 const effectiveProfile=useMemo(()=>profile||{id:session?.user?.id,name:"Aventureiro",avatar_url:null,level:1,total_xp:0,quests_completed_ever:0,max_streak_ever:0,usage_seconds:0,is_private:false,equipped_title:null},[profile,session]);
 const overall=levelInfo(effectiveProfile.total_xp||0);

 const userKey=session?.user?.id||"guest";const activityKey=`"codex-vitae-system-activity-v1":${userKey}`,missionKey=`"codex-vitae-system-missions-v1":${userKey}`;
 useEffect(()=>{if(!session)return;const a=readLocal(activityKey,null);setActivity(a&&a.date===today()?a:{date:today(),areas:[],posts:0,likes:0,messages:0,profileChanges:0,photo:false});setMissions(readLocal(missionKey,{}))},[session,activityKey,missionKey]);
 useEffect(()=>{if(session){localStorage.setItem(activityKey,JSON.stringify(activity));localStorage.setItem(missionKey,JSON.stringify(missions))}},[activity,missions,session,activityKey,missionKey]);
 const recordActivity=(kind,value)=>setActivity(a=>{const b=a.date===today()?a:{date:today(),areas:[],posts:0,likes:0,messages:0,profileChanges:0,photo:false};const n={...b,areas:[...new Set(b.areas||[])]};if(kind==="area"&&!n.areas.includes(value))n.areas.push(value);if(kind==="post")n.posts++;if(kind==="like")n.likes++;if(kind==="message")n.messages++;if(kind==="profile")n.profileChanges++;if(kind==="photo")n.photo=true;return n});
 useEffect(()=>{let mounted=true;(async()=>{try{const {data}=await supabase.auth.getSession();if(!mounted)return;setSession(data.session);if(data.session){try{const p=await getProfile(data.session.user.id);if(!mounted)return;setProfile(p);setName(p.name||"Aventureiro");setUsage(p.usage_seconds||0);sessionStart.current=Date.now()}catch{const p=await saveProfile({id:data.session.user.id,name:data.session.user.user_metadata?.name||"Aventureiro",level:1,total_xp:0,quests_completed_ever:0,max_streak_ever:0,usage_seconds:0,equipped_title:null});if(mounted){setProfile(p);setName(p.name||"Aventureiro")}}}}catch(e){if(mounted)setError(e.message)}finally{if(mounted)setLoading(false)}})();const {data:listener}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s));return()=>{mounted=false;listener.subscription.unsubscribe()}},[]);
 useEffect(()=>{if(!session)return;getFeed().then(setPosts).catch(e=>setError(e.message));getMyLikes(session.user.id).then(setLikes).catch(()=>{});getMyConversations(session.user.id).then(setConversations).catch(()=>{});const ch=subscribeToFeed(()=>{getFeed().then(setPosts).catch(()=>{});getMyLikes(session.user.id).then(setLikes).catch(()=>{})});return()=>{supabase.removeChannel(ch)}},[session]);
 useEffect(()=>{if(tab!=="board"||!session)return;getLeaderboard(boardMode).then(setBoard).catch(e=>setError(e.message))},[tab,boardMode,session]);
