useEffect(()=>{if(!session)return;const t=setInterval(async()=>{const elapsed=Math.floor((Date.now()-sessionStart.current)/1000);if(elapsed<10)return;const next=(profileRef.current?.usage_seconds||usageRef.current||0)+elapsed;try{const p=await updateProgress(session.user.id,{usage_seconds:next});sessionStart.current=Date.now();setUsage(next);setProfile(p)}catch{}},15000);return()=>clearInterval(t)},[session]);

 const GOAL_DIFFICULTIES={beginner:{label:"Iniciante",xp:20},easy:{label:"Fácil",xp:40},medium:{label:"Médio",xp:70},hard:{label:"Difícil",xp:110},nightmare:{label:"Pesadelo",xp:180}};
 const loadGoals=async()=>{if(!session)return;const {data,error}=await supabase.from("user_goals").select("*, goal_objectives(*)").eq("user_id",session.user.id).order("created_at",{ascending:false});if(error)throw error;setGoals(data||[])};
 useEffect(()=>{if(session)loadGoals().catch(e=>setError(e.message))},[session]);
 const createGoal=async()=>{const title=goalTitle.trim();if(title.length<2){setError("Dê um nome para sua meta.");return}setGoalBusy(true);try{const {data:g,error}=await supabase.from("user_goals").insert({user_id:session.user.id,title,description:goalDescription.trim(),deadline:goalDeadline||null,difficulty:goalDifficulty}).select().single();if(error)throw error;if(objectiveDraft.trim()){const xp=GOAL_DIFFICULTIES[goalDifficulty].xp;const {error:oe}=await supabase.from("goal_objectives").insert({goal_id:g.id,user_id:session.user.id,title:objectiveDraft.trim(),due_date:objectiveDate||goalDeadline||null,xp,position:0});if(oe)throw oe}setGoalTitle("");setGoalDescription("");setGoalDeadline("");setObjectiveDraft("");setObjectiveDate("");await loadGoals()}catch(e){setError(e.message)}finally{setGoalBusy(false)}};
 const addGoalObjective=async(goal)=>{const title=objectiveDraft.trim();if(!title)return;setGoalBusy(true);try{const list=goal.goal_objectives||[];const xp=GOAL_DIFFICULTIES[goal.difficulty]?.xp||70;const {error}=await supabase.from("goal_objectives").insert({goal_id:goal.id,user_id:session.user.id,title,due_date:objectiveDate||goal.deadline||null,xp,position:list.length});if(error)throw error;setObjectiveDraft("");setObjectiveDate("");await loadGoals()}catch(e){setError(e.message)}finally{setGoalBusy(false)}};
