 const activeMission=missions[difficulty]&&missions[difficulty].date===today()?missions[difficulty]:null;const mp=activeMission&&!activeMission.cancelled?missionProgress(activeMission):0;const activeMissionCount=Object.values(missions).filter(m=>m&&m.date===today()&&!m.cancelled&&!m.completed).length;const missionCard=<div className="cv-card"><div className="cv-section-head"><div><h2>Missões do sistema</h2><p className="cv-muted">Você pode manter uma missão ativa por dificuldade. O progresso é atualizado conforme você realiza as ações no site.</p></div><b>{activeMissionCount}/5 ativas</b></div><div className="cv-switch" style={{margin:"14px 0",display:"grid",gridTemplateColumns:"repeat(5,minmax(0,1fr))"}}>{DIFFICULTIES.map(d=>{const mm=missions[d.key]&&missions[d.key].date===today()?missions[d.key]:null;return <button key={d.key} className={difficulty===d.key?"active":""} onClick={()=>setDifficulty(d.key)}>{d.label}<small>{mm?.completed?"✓ concluída":mm?.cancelled?"✕ cancelada":mm?`${missionProgress(mm)}/${mm.target}`:`${d.xp} XP`}</small></button>})}</div>{!activeMission?<button className="cv-button" onClick={()=>missionFor(difficulty)}>Receber missão de {DIFFICULTIES.find(d=>d.key===difficulty)?.label}</button>:activeMission.cancelled?<div className="cv-quest"><div className="cv-quest-info"><b>Missão cancelada</b><small>Você não poderá receber outra missão desta dificuldade hoje.</small></div><X/></div>:<div className="cv-quest"><div className="cv-quest-info"><b>{activeMission.title}</b><small>{activeMission.desc}</small><div className="cv-progress"><span style={{width:`${Math.min(100,mp/activeMission.target*100)}%`}}/></div><small>{mp}/{activeMission.target} · +{activeMission.xp} XP</small></div>{activeMission.completed?<Check/>:missionReady(activeMission)?<div><button className="cv-button" disabled={saving} onClick={()=>claimMission(activeMission)}>{saving?"Verificando...":"Resgatar XP"}</button><button className="cv-button" style={{marginTop:8}} onClick={()=>cancelMission(activeMission)}>Cancelar</button></div>:<button className="cv-button" onClick={()=>cancelMission(activeMission)}>Cancelar</button>}</div>}</div>;
  const myGlobalRank=board.findIndex(p=>p.id===session?.user?.id)+1;
